<?php declare(strict_types=1); namespace Modules\Permissions\Controllers; use App\Http\Controllers\Controller; use Core\Http\Request; use Core\Http\Response; use Modules\Permissions\Repositories\PermissionRepository; use Modules\Permissions\Repositories\RoleRepository; use Modules\Permissions\Services\PermissionService; class RoleController extends Controller { public function __construct( private readonly RoleRepository $roles, private readonly PermissionRepository $permissions, private readonly PermissionService $permissionService, ) { } public function index(): Response { return $this->view('permissions::Admin.roles', [ 'title' => trans('common.roles_permissions'), 'roles' => $this->roles->all(['id' => 'asc']), 'permissions' => $this->permissions->all(['key' => 'asc']), ]); } public function updatePermissions(Request $request, int $id): Response { $request->validate(['permissions' => 'nullable|array']); $permissionIds = array_map('intval', (array) $request->input('permissions', [])); $this->permissionService->syncRolePermissions($id, $permissionIds); return $this->redirect(route('admin.roles.index')) ->with('_success', trans('common.saved')); } } 